import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 8
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    records = []
    try:
        for record in reader:
            if record:
                records.append(record)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    records[0][0] = records[0][0].lstrip("\ufeff")

    number_pattern = re.compile(r"^[\s$£€+-]*\d[\d,]*(?:\.\d+)?%?[\s]*$")
    date_pattern = re.compile(
        r"^\s*(?:\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}|\d{4}-\d{2}-\d{2})\s*$"
    )

    def header_score(record: list[str]) -> float:
        if len(record) != expected_width:
            return float("-inf")

        nonempty = [cell.strip() for cell in record]
        if not any(nonempty):
            return float("-inf")

        alpha_count = sum(any(char.isalpha() for char in cell) for cell in nonempty)
        data_like = sum(
            bool(number_pattern.match(cell) or date_pattern.match(cell))
            for cell in nonempty
        )
        unique_ratio = len(set(nonempty)) / len(nonempty)
        return alpha_count * 2 - data_like * 3 + unique_ratio

    candidates = [
        (header_score(record), index)
        for index, record in enumerate(records)
        if len(record) == expected_width
    ]

    if candidates:
        best_score = max(score for score, _ in candidates)
        header_index = next(
            index for score, index in candidates if score == best_score
        )
    else:
        header_index = 0

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    width = len(columns)

    def fit_width(record: list[str]) -> list[str]:
        if len(record) < width:
            return record + [""] * (width - len(record))
        if len(record) > width and width:
            return record[: width - 1] + [",".join(record[width - 1 :])]
        return record

    rows = [fit_width(record) for record in records[header_index + 1 :]]
    return {"columns": columns, "rows": rows}
